"},{"relativePath":"styles.css","content":"/* Order summary card. All selectors stay scoped to this plugin's own classes. */

.aui-order-summary {
  display: flex;
  flex-direction: column;
  gap: 12px;
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
  padding: 14px 16px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--card);
  color: var(--foreground);
  font-size: 13px;
  line-height: 1.5;
}

.aui-order-summary__header {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: flex-start;
  justify-content: space-between;
  min-width: 0;
}

.aui-order-summary__heading {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.aui-order-summary__eyebrow {
  font-size: 13px;
  font-weight: 600;
}

.aui-order-summary__order-no {
  overflow-wrap: anywhere;
  color: var(--muted-foreground);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.aui-order-summary__status {
  flex: none;
  padding: 2px 10px;
  border-radius: 999px;
  background: var(--muted);
  color: var(--muted-foreground);
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}

.aui-order-summary__status[data-status="paid"],
.aui-order-summary__status[data-status="completed"],
.aui-order-summary__status[data-status="delivered"],
.aui-order-summary__status[data-status="shipped"] {
  background: color-mix(in oklab, #10b981 16%, transparent);
  color: #047857;
}

.aui-order-summary__status[data-status="pending"],
.aui-order-summary__status[data-status="unpaid"],
.aui-order-summary__status[data-status="processing"] {
  background: color-mix(in oklab, #f59e0b 18%, transparent);
  color: #b45309;
}

.aui-order-summary__status[data-status="cancelled"],
.aui-order-summary__status[data-status="canceled"],
.aui-order-summary__status[data-status="refunded"],
.aui-order-summary__status[data-status="closed"] {
  background: color-mix(in oklab, #ef4444 16%, transparent);
  color: #b91c1c;
}

:is(.agent-ui-root, .agent-ui-conversation)[data-theme="dark"] .aui-order-summary__status[data-status="paid"],
:is(.agent-ui-root, .agent-ui-conversation)[data-theme="dark"] .aui-order-summary__status[data-status="completed"],
:is(.agent-ui-root, .agent-ui-conversation)[data-theme="dark"] .aui-order-summary__status[data-status="delivered"],
:is(.agent-ui-root, .agent-ui-conversation)[data-theme="dark"] .aui-order-summary__status[data-status="shipped"] {
  color: #34d399;
}

:is(.agent-ui-root, .agent-ui-conversation)[data-theme="dark"] .aui-order-summary__status[data-status="pending"],
:is(.agent-ui-root, .agent-ui-conversation)[data-theme="dark"] .aui-order-summary__status[data-status="unpaid"],
:is(.agent-ui-root, .agent-ui-conversation)[data-theme="dark"] .aui-order-summary__status[data-status="processing"] {
  color: #fbbf24;
}

:is(.agent-ui-root, .agent-ui-conversation)[data-theme="dark"] .aui-order-summary__status[data-status="cancelled"],
:is(.agent-ui-root, .agent-ui-conversation)[data-theme="dark"] .aui-order-summary__status[data-status="canceled"],
:is(.agent-ui-root, .agent-ui-conversation)[data-theme="dark"] .aui-order-summary__status[data-status="refunded"],
:is(.agent-ui-root, .agent-ui-conversation)[data-theme="dark"] .aui-order-summary__status[data-status="closed"] {
  color: #f87171;
}

.aui-order-summary__items {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.aui-order-summary__items-head {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: baseline;
  justify-content: space-between;
  color: var(--muted-foreground);
  font-size: 12px;
}

.aui-order-summary__item-count {
  font-variant-numeric: tabular-nums;
}

.aui-order-summary__item-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.aui-order-summary__item {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  justify-content: space-between;
  min-width: 0;
}

.aui-order-summary__item-main {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.aui-order-summary__item-name {
  overflow-wrap: anywhere;
  font-weight: 500;
}

.aui-order-summary__item-meta {
  color: var(--muted-foreground);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.aui-order-summary__item-subtotal {
  flex: none;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.aui-order-summary__toggle {
  align-self: flex-start;
  padding: 2px 0;
  border: 0;
  background: none;
  color: var(--primary);
  font: inherit;
  font-size: 12px;
  text-decoration: underline;
  text-underline-offset: 2px;
  cursor: pointer;
}

.aui-order-summary__toggle:hover {
  opacity: 0.8;
}

.aui-order-summary__toggle:focus-visible {
  border-radius: 4px;
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

.aui-order-summary__footer {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: baseline;
  justify-content: space-between;
  padding-top: 10px;
  border-top: 1px solid var(--border);
}

.aui-order-summary__total-label {
  color: var(--muted-foreground);
  font-size: 12px;
}

.aui-order-summary__total-amount {
  font-size: 16px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.aui-order-summary--invalid {
  border-style: dashed;
  background: var(--muted);
  color: var(--muted-foreground);
}

.aui-order-summary__invalid-text {
  margin: 0;
}
"}]}

{"path":"/src/agent-ui/application/i18n/messages.ts","content":"import type { AgentUILocaleCode } from "@za38.03/agent-ui-plugins";

/**
 * Project-owned business copy. Keep both locales complete (en-US / zh-CN) and
 * select them with the unified useAgentUILocaleCode() value.
 */
export type ProjectMessages = {
  orderSummary: {
    heading: string;
    orderNo: string;
    itemsHeading: string;
    quantity: string;
    unitPrice: string;
    total: string;
    collapse: string;
    invalid: string;
    expandMore: (hiddenCount: number) => string;
    itemCount: (count: number) => string;
    statusLabel: (status: string) => string;
  };
};

const STATUS_LABELS_ZH: Record<string, string> = {
  paid: "已支付",
  unpaid: "待支付",
  pending: "待支付",
  processing: "处理中",
  shipped: "已发货",
  delivered: "已送达",
  completed: "已完成",
  refunded: "已退款",
  cancelled: "已取消",
  canceled: "已取消",
  closed: "已关闭",
};

const STATUS_LABELS_EN: Record<string, string> = {
  paid: "Paid",
  unpaid: "Unpaid",
  pending: "Pending",
  processing: "Processing",
  shipped: "Shipped",
  delivered: "Delivered",
  completed: "Completed",
  refunded: "Refunded",
  cancelled: "Cancelled",
  canceled: "Cancelled",
  closed: "Closed",
};

const zhCN: ProjectMessages = {
  orderSummary: {
    heading: "订单摘要",
    orderNo: "订单号",
    itemsHeading: "商品",
    quantity: "数量",
    unitPrice: "单价",
    total: "合计金额",
    collapse: "收起商品清单",
    invalid: "订单数据格式不正确，暂时无法显示订单卡片。",
    expandMore: (hiddenCount) => `展开其余 ${hiddenCount} 件商品`,
    itemCount: (count) => `共 ${count} 件`,
    statusLabel: (status) => STATUS_LABELS_ZH[status.toLowerCase()] ?? status,
  },
};

const enUS: ProjectMessages = {
  orderSummary: {
    heading: "Order summary",
    orderNo: "Order no.",
    itemsHeading: "Items",
    quantity: "Qty",
    unitPrice: "Unit price",
    total: "Total",
    collapse: "Show less",
    invalid: "The order data could not be read, so the order card is unavailable.",
    expandMore: (hiddenCount) => `Show ${hiddenCount} more item${hiddenCount === 1 ? "" : "s"}`,
    itemCount: (count) => `${count} item${count === 1 ? "" : "s"}`,
    statusLabel: (status) => STATUS_LABELS_EN[status.toLowerCase()] ?? status,
  },
};

const messages: Record<AgentUILocaleCode, ProjectMessages> = {
  "zh-CN": zhCN,
  "en-US": enUS,
};

export function getProjectMessages(locale: AgentUILocaleCode): ProjectMessages {
  return messages[locale] ?? zhCN;
}
"}

